(()=>{'use strict';const $=id=>document.getElementById(id),fmt=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}),money=v=>Number.isFinite(v)?fmt.format(v)+' ₽':'—',esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let report,drafts=[];
function card(label,value,note){return `<article class="metric"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></article>`}
function metricRender(){const a=report.accruals,b=report.bankCash,d=report.debt.summary;$('metrics').innerHTML=card('Начисления Ozon',money(a.value),a.status==='complete'?'Полный выбранный период':a.knownSubtotal===null?'Нет данных':'Известно частично: '+money(a.knownSubtotal))+card('Поступления в банк',money(b.receipts),b.source)+card('Денежный поток',money(report.operatingCashFlow.value),report.operatingCashFlow.reason)+card('Прибыль',money(report.profit.value),'Смотреть отдельный расчёт по начислениям и себестоимости');$('coverage').textContent=`Период ${report.period.from} — ${report.period.to} · ${a.status==='complete'?'полные данные':'данные неполные'}`;$('sources').innerHTML=a.sources.map(s=>`<div>${esc(s.name)} · ${esc(s.status==='complete'?'полный период':'неполно/нет данных')} · ${esc(s.period?s.period.from+' — '+s.period.to:'период неизвестен')} · обновлено ${esc(s.updatedAt?new Date(s.updatedAt).toLocaleString('ru-RU'):'неизвестно')} · ${esc(s.source||'источник отсутствует')}</div>`).join('')||'<div>Подключённых источников начислений нет.</div>';
 const max=Math.max(1,...a.series.flatMap(x=>[x.positive,Math.abs(x.negative)]));$('chart').innerHTML=a.series.map(x=>`<div class="day" data-tip="${esc(x.date)} · ${esc(money(x.net))}"><i class="bar pos" style="height:${Math.max(1,x.positive/max*100)}%"></i><i class="bar neg" style="height:${Math.max(1,Math.abs(x.negative)/max*100)}%"></i></div>`).join('')||'<div class="empty">Нет начислений в выбранном периоде</div>';
 $('debt-source').textContent=report.debt.source+(report.debt.updatedAt?' · обновлено '+new Date(report.debt.updatedAt).toLocaleString('ru-RU'):'');$('debt-metrics').innerHTML=card('Действующих договоров',String(d.activeCount),'По ручному реестру')+card('Основной долг',money(d.outstandingPrincipal),'Только подтверждённые остатки')+card('Погашено тела',money(d.principalPaid),'Финансовый поток, не расход')+card('Проценты',money(d.interestExpense),'Финансовый расход')+card('Комиссии',money(d.feeExpense),'Финансовый расход');
 const loans=new Map(report.debt.loans.map(x=>[x.id,x]));$('loans').innerHTML=report.debt.loans.map(x=>`<tr><td><b>${esc(x.lender)}</b><br>${esc(x.agreementNumber)} · ${esc(x.status==='active'?'действует':'закрыт')}</td><td>${esc(x.signedDate)}</td><td class="num">${money(x.originalPrincipal)}</td><td class="num">${money(x.outstandingPrincipal)}</td><td class="num">${Number.isFinite(x.annualRatePercent)?fmt.format(x.annualRatePercent)+'%':'—'}</td><td>${esc(x.sourceNote)}</td><td><button class="secondary add-payment" data-id="${esc(x.id)}">Платёж</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Договоры не внесены. Нулевой долг не предполагается.</td></tr>';$('payments').innerHTML=report.debt.payments.filter(x=>x.date>=report.period.from&&x.date<=report.period.to).sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(loans.get(x.loanId)?.agreementNumber||'Договор не найден')}</td><td class="num">${money(x.principal)}</td><td class="num">${money(x.interest)}</td><td class="num">${money(x.fee)}</td><td>${esc(x.sourceNote)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Подтверждённых платежей за период нет.</td></tr>';document.querySelectorAll('.add-payment').forEach(b=>b.onclick=()=>{document.querySelector('#payment-form [name=loanId]').value=b.dataset.id;$('payment-dialog').showModal()})}
function renderDrafts(){const value=f=>f?.value===null||f?.value===undefined||f?.value===''?'не распознано':String(f.value),source=f=>f?.source?`${f.source.page?'стр. '+f.source.page:'DOCX'} · ${f.source.excerpt}`:'источник не найден';$('contract-drafts').innerHTML=drafts.map(d=>{const f=d.fields||{},known=[f.lender,f.agreementNumber,f.signedDate,f.originalPrincipal].filter(x=>x?.value!==null&&x?.value!==undefined).length;return `<article class="draft-card"><div><strong>${esc(d.fileName)}</strong><small>${esc(d.format.toUpperCase())} · ${fmt.format(d.size)} байт · распознано ${known} из 4 основных полей</small><small>${esc((d.warnings||[]).join(' · ')||'Поля требуют проверки по оригиналу.')}</small></div><button class="secondary review-draft" data-id="${esc(d.id)}">Проверить черновик</button></article>`}).join('')||'<p class="empty">Загруженных договоров пока нет.</p>';document.querySelectorAll('.review-draft').forEach(button=>button.onclick=()=>{const d=drafts.find(x=>x.id===button.dataset.id),form=$('loan-form'),f=d.fields||{};form.reset();for(const [name,field] of [['lender',f.lender],['agreementNumber',f.agreementNumber],['signedDate',f.signedDate],['originalPrincipal',f.currency?.value==='RUB'?f.originalPrincipal:null],['annualRatePercent',f.ratePeriod?.value==='annual'?f.annualRatePercent:null]])form.elements[name].value=field?.value??'';form.elements.sourceNote.value=d.suggestedSourceNote||'';$('draft-review').hidden=false;$('draft-review').innerHTML='<b>Черновик распознавания — сверьте с оригиналом</b>'+Object.entries(f).filter(([,x])=>x?.value!==null&&x?.value!==undefined).map(([name,x])=>`<p><strong>${esc(name)}</strong>: ${esc(value(x))}<small>${esc(source(x))}</small></p>`).join('')+(f.currency?.value&&f.currency.value!=='RUB'?'<p class="warning">Валюта не RUB. Сумма не перенесена: текущий реестр принимает только рублёвые договоры.</p>':'')+(f.rate?.value!==null&&f.ratePeriod?.value!=='annual'?'<p class="warning">Ставка не подтверждена как годовая и не перенесена автоматически.</p>':'');$('loan-save').textContent='Принять в реестр';$('loan-dialog').showModal()})}
async function loadDrafts(){const r=await fetch('/api/finance/contracts'),j=await r.json();if(!r.ok)throw Error(j.error||'Не удалось загрузить черновики');drafts=Array.isArray(j.drafts)?j.drafts:[];renderDrafts()}
async function uploadContract(file){if(!file)return;const button=$('upload-contract');button.disabled=true;$('message').textContent='Локально разбираем документ…';try{const r=await fetch('/api/finance/contracts',{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(file.name)},body:file}),j=await r.json();if(!r.ok)throw Error(j.error||'Не удалось разобрать договор');$('message').textContent=j.duplicate?'Этот файл уже загружен. Открыт прежний черновик.':'Черновик готов. Проверьте каждое поле по оригиналу.';await loadDrafts()}finally{button.disabled=false;$('contract-file').value=''}}
async function load(){try{$('message').textContent='';const r=await fetch(`/api/finance?from=${encodeURIComponent($('from').value)}&to=${encodeURIComponent($('to').value)}`);const j=await r.json();if(!r.ok)throw Error(j.error||'Не удалось загрузить финансы');report=j;metricRender();await loadDrafts()}catch(e){$('message').textContent=e.message}}
async function send(url,form){const body=Object.fromEntries(new FormData(form));const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),j=await r.json();if(!r.ok)throw Error(j.error||'Не удалось сохранить');form.closest('dialog').close();form.reset();await load()}
const today=new Date().toISOString().slice(0,10),from=new Date(Date.parse(today+'T00:00:00Z')-29*86400000).toISOString().slice(0,10);$('from').value=from;$('to').value=today;$('period').onsubmit=e=>{e.preventDefault();load()};$('show-loan').onclick=()=>{$('loan-form').reset();$('draft-review').hidden=true;$('draft-review').innerHTML='';$('loan-save').textContent='Сохранить';$('loan-dialog').showModal()};$('upload-contract').onclick=()=>$('contract-file').click();$('contract-file').onchange=()=>uploadContract($('contract-file').files[0]).catch(error=>$('message').textContent=error.message);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('loan-form').onsubmit=e=>{e.preventDefault();send('/api/finance/loans',e.currentTarget).catch(x=>$('message').textContent=x.message)};$('payment-form').onsubmit=e=>{e.preventDefault();send('/api/finance/payments',e.currentTarget).catch(x=>$('message').textContent=x.message)};load();})();
